oxy_webhelp_navlinks = {"azr_container_immutability-d39536e10008":{"topics":[{"title":"Immutability lock period for container-level immutability","shortdesc":"<p class=\"shortdesc\">The immutable archival locations on Rubrik clusters running Rubrik CDM versions         earlier than 9.1 rely on the container-level immutability feature of Azure for data         immutability. In this case, an immutability lock period is required for the archival         location, and the period is limited by the retention period of the associated SLA         Domain.<\/p>","href":"archival\/azr_immutability_lock_periods.html","attributes":{"data-id":"azr_immutability_lock_periods"},"menu":{"hasChildren":false},"tocID":"azr_immutability_lock_periods-d39536e10022","topics":[]}]}};